type CaseRow = { id: string; referenceNumber: string; title: string; description: string; category: Category; subcategory?: { name: string } | null; status: string; priority: string; severity?: string; location: string | null; latitude?: number | null; longitude?: number | null; slaDueAt: string | null; slaMetrics?: { state: string; remainingMs: number | null; consumptionPercent: number | null; calculatedAt: string; dueAt: string | null }; createdAt: string; updatedAt: string; department?: Department | null; citizenProfile?: { user?: { id: string; fullName: string; email?: string; phone?: string | null } }; assignments?: Assignment[] };
type Assignment = { id: string; assignedAt: string; endedAt: string | null; assignedTo?: { fullName: string } | null; assignedBy?: { fullName: string }; team?: { name: string } | null };
type CaseDetail = CaseRow & { citizenProfile?: { user?: { fullName: string; email?: string; phone?: string | null } }; comments: { id: string; body: string; isInternal: boolean; createdAt: string; author: { fullName: string } }[]; statusHistory: { id: string; fromStatus: string | null; toStatus: string; note: string | null; createdAt: string; changedBy: { fullName: string } }[]; escalations: { id: string; level: number; reason: string; createdAt: string }[]; attachments: { id: string; fileName: string; contentType: string; sizeBytes: number; createdAt: string }[] };
type Page<T> = { data: T[]; pagination: { page: number; pageSize: number; total: number; pages: number } };
type Analytics = { total: number; byStatus: Record<string, number>; resolvedThisMonth: number; overdue: number; escalations: number; slaCompliance: number | null; byDepartment: { name: string; count: number }[]; byCategory: { name: string; count: number }[]; weeklyActivity: { day: string; received: number; resolved: number }[] };
